'multi_agent_checkpoint_path','','string','Multi-Agent SAC checkpoint 目录','2026-09-02 10:16:14'),('multi_agent_eval_schema','citylearn_challenge_2023_phase_2_online_evaluation_1','string','Multi-agent.py 评估 schema','2026-09-16 16:32:37'),('multi_agent_explore','false','string','Multi-Agent 评估时是否开启 explore','2026-09-16 16:32:37'),('multi_agent_train_epochs','20','number','Multi-Agent SAC 训练轮数','2026-09-16 16:32:37'),('outdoor_floor_allow_when_under_setpoint','false','string','室外保底允许低于设定时启用','2026-09-16 16:32:37'),('outdoor_floor_max_overheat_c','1.0','number','室外保底最大过热阈值outdoor_floor_max_overheat_c','2026-09-16 16:32:37'),('outdoor_gap_deadband_c','5.0','number','室外保底死区outdoor_gap_deadband_c','2026-09-16 16:32:37'),('post_outage_forbid_charge_when_overheat','true','string','复电窗口过热时禁止充电','2026-09-16 16:32:37'),('post_outage_max_ele_charge','0.15','number','复电窗口ELE充电上限','2026-09-16 16:32:37'),('post_outage_overheat_c','0.5','number','复电缓充过热阈值post_outage_overheat_c','2026-09-16 16:32:37'),('post_outage_relax_steps','4','number','复电缓充窗口步数','2026-09-16 16:32:37'),('post_outage_soft_charge_enabled','true','string','是否启用复电缓充','2026-09-16 16:32:37'),('post_outage_tmp_cap_enabled','true','string','是否启用复电TMP帽/斜坡','2026-09-16 16:32:37'),('post_outage_tmp_cap_steps','4','number','复电TMP帽窗口步数','2026-09-16 16:32:37'),('post_outage_tmp_max_start','0.4','number','复电首步TMP上限','2026-09-16 16:32:37'),('post_outage_tmp_ramp','true','string','复电TMP是否线性爬升','2026-09-16 16:32:37'),('post_outage_tmp_stagger','true','string','复电TMP分栋错峰','2026-09-16 16:32:37'),('post_outage_waive_min_soc','true','string','复电窗口豁免小时min_soc硬充','2026-09-16 16:32:37'),('price_aware_battery_enabled','true','string','是否启用电价感知电池','2026-09-16 16:32:37'),('price_global_reserve_enabled','true','string','全局韧性地板（非停电放电不可击穿）','2026-09-16 16:32:37'),('price_high_discharge_ele','0.15','number','高价强制放电ELE幅度','2026-09-16 16:32:37'),('price_high_forbid_charge','true','string','高价禁止充电','2026-09-16 16:32:37'),('price_high_force_discharge','true','string','高价高SOC强制放电','2026-09-16 16:32:37'),('price_high_quantile','0.75','number','高价分位数','2026-09-16 16:32:37'),('price_high_soc_threshold','0.7','number','高价强制放电SOC阈值','2026-09-16 16:32:37'),('price_history_min_steps','48','number','电价历史最少样本步数','2026-09-16 16:32:37'),('price_low_charge_ele','0.15','number','低价补电ELE幅度','2026-09-16 16:32:37'),('price_low_quantile','0.25','number','低价分位数','2026-09-16 16:32:37'),('price_low_search_boost','true','string','低价树搜索抬高SOC下限促补电','2026-09-16 16:32:37'),('price_low_target_soc','0.75','number','低价补电目标SOC','2026-09-16 16:32:37'),('price_min_reserve_soc','0.55','number','高价放电韧性地板SOC','2026-09-16 16:32:37'),('residual_action_mask','{\"dhw\":false,\"ele\":true,\"tmp\":false}','json','CHESCA-ResMARL 可修正动作维 mask','2026-09-16 16:32:37'),('residual_alpha','0.15','number','CHESCA-ResMARL 残差强度 α∈[0,1]','2026-09-16 16:32:37'),('resmarl_after_safety','true','string','残差是否在安全审查之后施加','2026-09-16 16:32:37'),('resmarl_enabled','true','string','兼容字段：是否残差由入口脚本决定','2026-09-16 16:32:37'),('resmarl_eval_schema','citylearn_challenge_2023_phase_2_online_evaluation_1','string','CHESCA_ResMARL.py 仿真/KPI 评估 schema','2026-09-16 16:32:37'),('resmarl_policy_path','D:\\citylearn-demo\\citylearnpy\\checkpoints\\resmarl_policy.pt','string','ResMARL策略checkpoint路径（空=无模型）','2026-07-22 01:09:27'),('schema_split_enabled','true','string','是否启用训测 schema 分离（方案 A）','2026-09-16 16:32:37'),('tau','1','number','预测优化步长tau','2026-09-16 16:32:37'),('tmp_max_reduction_percent','0.0','number','冷机最大削减比例TMP_max_reduction_percent','2026-09-16 16:32:37'),('train_schema','citylearn_challenge_2023_phase_2_local_evaluation','string','Multi-Agent SAC 训练 schema','2026-09-16 16:32:37'),('use_lagged_dynamics_indoor','true','string','PID使用滞后动力学室温indoor[-2]','2026-09-16 16:32:37');
