INSERT INTO `algorithm_param_config` (`id`, `create_time`, `name`, `param_name`, `if_system`, `value_type`, `desc`, `default_value`, `is_member`, `key_alias`, `value_alias`) VALUES (1,'2026-09-23 00:54:12','训练数据集','train-schema',1,'special','训练用的数据集：从已启用的数据集中选一个，保存的是数据集 id。',NULL,0,NULL,NULL),(2,'2026-09-23 00:54:12','评估数据集','eval-schema',1,'special','评估用的数据集：同样保存数据集 id，一般与训练数据集配套选择。',NULL,0,NULL,NULL),(3,'2026-09-23 02:02:47','训练轮数','train-epochs',1,'num','训练的总轮数（epochs），只能填正整数。',NULL,0,NULL,NULL),(7,'2026-09-23 17:09:05','预测优化步长','tau',0,'ratio','电池树搜索向前看的步数：预测未来第 tau 步的净负荷再决定当前充放电动作。步数越大越有远见，搜索开销也越大。','[{\"key\":\"1\",\"value\":\"1 步\"},{\"key\":\"2\",\"value\":\"2 步\"},{\"key\":\"3\",\"value\":\"3 步\"}]',1,NULL,NULL),(8,'2026-09-23 17:09:05','电池树搜索适应度类型','balance_type',0,'ratio','决定电池树搜索里「什么叫代价最小」：A=偏离历史净负荷均值；B=偏离上一步净负荷（更平滑）；C=偏离历史均值与下一步预测的中点（默认）。','[{\"key\":\"A\",\"value\":\"A — 跟踪历史均值\"},{\"key\":\"B\",\"value\":\"B — 抑制步间波动\"},{\"key\":\"C\",\"value\":\"C — 跟踪均值与预测中点\"}]',1,NULL,NULL),(9,'2026-09-23 17:09:05','增负荷阈值系数','B_low',0,'num','净负荷低于「均值 − B_low×标准差」时触发增负荷（充电）。默认 1.18，越大越不轻易增负荷。',NULL,1,NULL,NULL),(10,'2026-09-23 17:09:05','减负荷阈值系数','B_high',0,'num','净负荷高于「均值 + B_high×标准差」时触发减负荷（放电）。默认 1.0，越小越容易触发减负荷。',NULL,1,NULL,NULL),(11,'2026-09-23 19:31:58','电价感知','price_aware_battery_enabled',0,'bool','是否启用电价感知电池：用最近一段时间的电价分布判断「现在贵不贵」，贵则少充、便宜则多充电。关闭后下方高/低价规则不生效（韧性地板若单独开启仍可能约束放电）。',NULL,1,NULL,NULL),(12,'2026-09-23 19:31:58','高价分位数','price_high_quantile',0,'num','高价分位数（0.5~0.99）：电价高于该分位视为「高价」，默认 0.75。',NULL,1,NULL,NULL),(13,'2026-09-23 19:31:58','低价分位数','price_low_quantile',0,'num','低价分位数（0.01~0.5）：电价低于该分位视为「低价」，默认 0.25。',NULL,1,NULL,NULL),(14,'2026-09-23 19:31:58','电价历史最少步数','price_history_min_steps',0,'num','电价历史最少样本步数（8~720）：历史样本不足该步数时不做分位数判断，默认 48。',NULL,1,NULL,NULL),(15,'2026-09-23 19:31:58','高价禁止充电','price_high_forbid_charge',0,'bool','开启后高价时段禁止充电（ELE≤0），避免电价高时还充电。默认开启。',NULL,1,NULL,NULL),(16,'2026-09-23 19:31:58','高价强制放电','price_high_force_discharge',0,'bool','开启后在高价且 SOC 够高时主动放电，用电池电顶替买电，降低电费与净负荷。默认开启。',NULL,1,NULL,NULL),(17,'2026-09-23 19:31:58','高价强放 SOC 阈值','price_high_soc_threshold',0,'num','高价强制放电的 SOC 阈值（0~1）：SOC 高于该值才触发强制放电，默认 0.70。',NULL,1,NULL,NULL),(18,'2026-09-23 19:31:58','强制放电幅度','price_high_discharge_ele',0,'num','高价强制放电的 ELE 幅度（0~1）：单次放电削减的用电比例，默认 0.15。',NULL,1,NULL,NULL),(19,'2026-09-23 19:31:58','全局韧性地板','price_global_reserve_enabled',0,'bool','开启后中/高/低价放电都受韧性地板约束，树搜索的 SOC 下限也会抬到地板以上；关闭则中价放电不起效。默认开启。',NULL,1,NULL,NULL),(20,'2026-09-23 19:31:58','韧性地板 SOC','price_min_reserve_soc',0,'num','高价放电的韧性地板 SOC（0~1）：放电不得击穿该下限，默认 0.55。',NULL,1,NULL,NULL),(21,'2026-09-23 19:31:58','低价补电目标 SOC','price_low_target_soc',0,'num','低价时补电的目标 SOC（0~1），默认 0.80。',NULL,1,NULL,NULL),(22,'2026-09-23 19:31:58','低价补电幅度','price_low_charge_ele',0,'num','低价补电的 ELE 幅度（0~1）：单次补电抬升的用电比例，默认 0.25。',NULL,1,NULL,NULL),(23,'2026-09-23 19:31:58','低价树搜索促补电','price_low_search_boost',0,'bool','开启后低价时抬高树搜索的 SOC 下限，促使一步充到「当前 SOC + 补电幅度」，让搜索更积极抓住便宜电。默认开启。',NULL,1,NULL,NULL),(26,'2026-09-23 20:54:53','冷机最大削减比例','TMP_max_reduction_percent',0,'num','减负荷时空调最多能被砍掉的比例（0~100）。0=保护舒适不砍空调；100=允许把空调几乎关停来保电网。',NULL,1,NULL,NULL),(27,'2026-09-23 20:54:53','过热保底系数','min_cool_per_c_overheat',0,'num','室内比设定温度每高 1°C，至少按「系数 × 额定制冷功率」要电（0~2）。防止 PID 还没跟上时房间继续升温。',NULL,1,NULL,NULL),(28,'2026-09-23 20:54:53','室外保底系数','min_cool_per_c_outdoor_gap',0,'num','按「室外温度 − 室内设定」额外抬一点制冷（0~1）。设为 0 则完全关闭室外保底。',NULL,1,NULL,NULL),(29,'2026-09-23 20:54:53','室外死区','outdoor_gap_deadband_c',0,'num','只有「室外 − 设定」超过该死区才启用室外保底（°C，0~30），避免误开空调。',NULL,1,NULL,NULL),(30,'2026-09-23 20:54:53','室外保底最大过热阈值','outdoor_floor_max_overheat_c',0,'num','仅当室内过热还「不太严重」（0 ≤ 过热 < 该值）时才叠加室外保底（°C，0~10），避免双重加码浪费电。',NULL,1,NULL,NULL),(31,'2026-09-23 20:54:53','冷负荷前馈比例','cooling_demand_feedforward_frac',0,'num','至少按冷负荷的该比例要电（0~1），不等 PID 纠偏先按负荷预报预开一点空调。设为 0 关闭。',NULL,1,NULL,NULL),(32,'2026-09-23 20:54:53','前馈仅过热时启用','demand_feedforward_only_when_overheat',0,'bool','开启：只有室内已经过热才用冷负荷前馈。关闭：室温刚贴设定时也能预开空调，舒适更稳但略费电。',NULL,1,NULL,NULL),(33,'2026-09-23 20:54:53','室外保底允许低于设定','outdoor_floor_allow_when_under_setpoint',0,'bool','开启：即使室内比设定还凉一点，只要室外很热仍可按室外温差保底预冷；关闭：室内低于设定时不再加室外保底。',NULL,1,NULL,NULL),(34,'2026-09-23 20:54:53','低于设定清掉开环保底','clear_open_loop_floor_when_under_setpoint',0,'bool','开启后：室内低于设定时清空室外保底与冷负荷前馈，只留 PID。',NULL,1,NULL,NULL),(35,'2026-09-23 20:54:53','PID 使用滞后动力学室温','use_lagged_dynamics_indoor',0,'bool','开启：PID 用「上一拍已落地」的室内温，与建筑动力学对齐，减少看错温度导致的震荡。',NULL,1,NULL,NULL),(36,'2026-09-23 20:54:53','仅当滞后室温更热时启用','lagged_indoor_only_when_hotter',0,'bool','开启：只有滞后室温比最新观测更热、且温差超过裕度时才改用滞后温（偏保守防闷热）；关闭：总开关打开就始终用滞后温。',NULL,1,NULL,NULL),(37,'2026-09-23 20:54:53','滞后更热裕度','lagged_indoor_hotter_margin_c',0,'num','滞后温要比最新观测至少高这么多才切换（°C，0~10），用来过滤噪声。',NULL,1,NULL,NULL),(38,'2026-09-23 20:54:53','TMP 功率帽','post_outage_tmp_cap_enabled',0,'bool','开启：电力恢复后一段时间内限制空调功率，避免三栋楼空调一步拉满造成的用电高峰；关闭：复电第一步即可满功率制冷。',NULL,1,NULL,NULL),(39,'2026-09-23 20:54:53','TMP 功率帽窗口步数','post_outage_tmp_cap_steps',0,'num','限制持续多少个仿真步（0~48）。例：4 步表示复电后约 4 小时内逐步放开。',NULL,1,NULL,NULL),(40,'2026-09-23 20:54:53','首步 TMP 上限','post_outage_tmp_max_start',0,'num','电力恢复那一步允许的最大 TMP（0~1）。0.40 ≈ 最多开到满功率的 40%。',NULL,1,NULL,NULL),(41,'2026-09-23 20:54:53','线性爬升到满功率','post_outage_tmp_ramp',0,'bool','开启：上限从「首步上限」线性升到 1.0；关闭：维持首步上限，结束限制步数才解除。',NULL,1,NULL,NULL),(42,'2026-09-23 20:54:53','分栋错峰','post_outage_tmp_stagger',0,'bool','开启：Building0 先爬坡，其余各晚 1 步，避免三栋同时拉满。',NULL,1,NULL,NULL),(43,'2026-09-23 20:54:53','电力恢复后缓充','post_outage_soft_charge_enabled',0,'bool','开启：复电后几步内限制每步充电量、过热时优先把电留给空调；关闭后下列缓充规则不生效。',NULL,1,NULL,NULL),(44,'2026-09-23 20:54:53','缓充窗口步数','post_outage_relax_steps',0,'num','复电后连续多少步生效（含刚复电的第 0 步，0~48）。例：4 ≈ 复电后约 4 小时内按缓充规则。',NULL,1,NULL,NULL),(45,'2026-09-23 20:54:53','避免SOC强制充电','post_outage_waive_min_soc',0,'bool','开启：不再强制把 SOC 充到该小时下限，避免用电高峰；关闭：仍按小时下限充电，峰值更大。',NULL,1,NULL,NULL),(46,'2026-09-23 20:54:53','ELE 充电上限','post_outage_max_ele_charge',0,'num','缓充窗口内每一步最多充多少（相对 SOC，0~1）。0.15 ≈ 每步最多充约 15% 电量。',NULL,1,NULL,NULL),(47,'2026-09-23 20:54:53','过热时禁止充电','post_outage_forbid_charge_when_overheat',0,'bool','开启：室内过热超过阈值时强制 ELE≤0，把电力优先留给制冷。',NULL,1,NULL,NULL),(48,'2026-09-23 20:54:53','过热阈值','post_outage_overheat_c',0,'num','室内比设定高出多少算过热、禁止充电（°C，0~20）。',NULL,1,NULL,NULL),(49,'2026-09-23 20:54:53','正常时段 SOC 上限','max_soc_normal',0,'num','电网正常时电池最多充到多少（0~1）。例：0.99 几乎可充满，减少过充风险。',NULL,1,NULL,NULL),(50,'2026-09-23 20:54:53','停电时段 SOC 上限','max_soc_outage',0,'num','停电期间允许的 SOC 上限（0~1），通常低于正常上限。',NULL,1,NULL,NULL),(51,'2026-09-23 20:54:53','停电 SOC 最大降幅','max_soc_reduction_in_outage',0,'num','停电期间相对停电前允许下降多少电（0~1），限制「一口气把电放光」。',NULL,1,NULL,NULL),(52,'2026-09-23 20:54:53','小时下限','min_soc_per_hour',0,'map','24 个小时各自的电池 SOC 下限（0~1）。该小时电池「尽量不要低于」的电量；例：傍晚高峰设 0.7，算法会倾向提前充电、高峰时还能放电支援。','[{\"key\":\"0\",\"value\":\"0.6\"},{\"key\":\"1\",\"value\":\"0.65\"},{\"key\":\"2\",\"value\":\"0.72\"},{\"key\":\"3\",\"value\":\"0.78\"},{\"key\":\"4\",\"value\":\"0.8\"},{\"key\":\"5\",\"value\":\"0.85\"},{\"key\":\"6\",\"value\":\"0.8\"},{\"key\":\"7\",\"value\":\"0.75\"},{\"key\":\"8\",\"value\":\"0.7\"},{\"key\":\"9\",\"value\":\"0.6\"},{\"key\":\"10\",\"value\":\"0.5\"},{\"key\":\"11\",\"value\":\"0.6\"},{\"key\":\"12\",\"value\":\"0.65\"},{\"key\":\"13\",\"value\":\"0.65\"},{\"key\":\"14\",\"value\":\"0.7\"},{\"key\":\"15\",\"value\":\"0.7\"},{\"key\":\"16\",\"value\":\"0.7\"},{\"key\":\"17\",\"value\":\"0.65\"},{\"key\":\"18\",\"value\":\"0.7\"},{\"key\":\"19\",\"value\":\"0.6\"},{\"key\":\"20\",\"value\":\"0.6\"},{\"key\":\"21\",\"value\":\"0.6\"},{\"key\":\"22\",\"value\":\"0.6\"},{\"key\":\"23\",\"value\":\"0.55\"}]',1,'选择时段','电池 SOC 下限'),(57,'2026-10-08 14:28:18','纯CHESCA 评估数据集','eval_schema',0,'special','CHESCA.py 仿真与 KPI 用的数据集（对应命令行 --eval_schema）。从已启用的数据集中选一个，库内存数据集 id；不选则用脚本默认。',NULL,1,NULL,NULL),(58,'2026-10-08 17:57:14','残差强度 α','residual_alpha',0,'num','CHESCA-ResMARL 残差强度：a_final = (1-α)·a_CHESCA + α·a_SAC（0~1；设 0 等价于纯 CHESCA）','0.15',1,NULL,NULL),(59,'2026-10-08 17:57:14','残差动作掩码','residual_action_mask',0,'map','逐维掩码（键取 dhw / ele / tmp，值为 true/false）：值为 false 的维度保持 CHESCA 原值，只让被放行的维度接受 SAC 修正。默认只放行 ele（电池充放电）。','[{\"key\":\"dhw\",\"value\":\"false\"},{\"key\":\"ele\",\"value\":\"true\"},{\"key\":\"tmp\",\"value\":\"false\"}]',1,'维度','是否放行'),(60,'2026-10-08 17:57:14','安全审查后叠加残差','resmarl_after_safety',0,'bool','true（默认）= 先做安全审查（动作上下限裁剪），再叠加 SAC 残差；false = 先叠加再审查。两种顺序会给出不同的 a_final，做消融时才需要改成 false。','true',1,NULL,NULL);
